files=json.loads('{"app/Services/AdminService.php": "<?php\\n\\nnamespace App\\\\Services;\\n\\nuse App\\\\Enums\\\\UserTypeEnum;\\nuse App\\\\Enums\\\\VehicleTypeEnum;\\nuse App\\\\Enums\\\\PickupShipmentStatusEnum;\\nuse App\\\\Enums\\\\PdvCommissionTypeEnum;\\nuse App\\\\Jobs\\\\CreateDefaultUserSettingsJob;\\nuse App\\\\Jobs\\\\SendShipmentStatusUpdatedMailJob;\\nuse App\\\\Models\\\\DiscountCoupon;\\nuse App\\\\Models\\\\Faq;\\nuse App\\\\Models\\\\Shipment;\\nuse App\\\\Models\\\\Tag;\\nuse App\\\\Models\\\\TagPurchase;\\nuse App\\\\Models\\\\User;\\nuse App\\\\Models\\\\Pdv;\\nuse App\\\\Models\\\\Vehicle;\\nuse Carbon\\\\Carbon;\\nuse Illuminate\\\\Auth\\\\Access\\\\AuthorizationException;\\nuse Illuminate\\\\Support\\\\Facades\\\\Hash;\\nuse Illuminate\\\\Validation\\\\ValidationException;\\n\\nclass AdminService\\n{\\n    public function userTotals(): array\\n    {\\n        $active = User::query()\\n            ->where(\'type\', UserTypeEnum::Client->value)\\n            ->count();\\n\\n        $pdv = User::query()\\n            ->where(\'type\', UserTypeEnum::Client->value)\\n            ->whereNotNull(\'pdv_id\')\\n            ->count();\\n\\n        $deleted = User::withTrashed()\\n            ->where(\'type\', UserTypeEnum::Client->value)\\n            ->whereNotNull(\'deleted_at\')\\n            ->count();\\n\\n        return [\\n            \'active\'  => $active,\\n            \'pdv\'     => $pdv,\\n            \'deleted\' => $deleted,\\n        ];\\n    }\\n\\n    public function vehicleTotals(): array\\n    {\\n        $registered = Vehicle::query()\\n            ->whereNull(\'deleted_at\')\\n            ->count();\\n\\n        $deleted = Vehicle::query()\\n            ->whereNotNull(\'deleted_at\')\\n            ->count();\\n\\n        $totalsByType = Vehicle::query()\\n            ->selectRaw(\'type, COUNT(*) as total\')\\n            ->whereNull(\'deleted_at\')\\n            ->groupBy(\'type\')\\n            ->pluck(\'total\', \'type\');\\n\\n        $byType = collect(VehicleTypeEnum::cases())\\n            ->map(static fn(VehicleTypeEnum $type): array => [\\n                \'id\' => $type->value,\\n                \'label\' => $type->label(),\\n                \'total\' => (int) ($totalsByType[$type->value] ?? 0),\\n            ])\\n            ->values()\\n            ->all();\\n\\n        return [\\n            \'registered\' => $registered,\\n            \'by_type\' => $byType,\\n            \'deleted\' => $deleted,\\n        ];\\n    }\\n\\n    public function users(?string $search = null): \\\\Illuminate\\\\Pagination\\\\LengthAwarePaginator\\n    {\\n        $query = User::query()\\n            ->withCount([\'vehicles\', \'tagPurchases\'])\\n            ->where(\'type\', UserTypeEnum::Client->value)\\n            ->orderByDesc(\'created_at\');\\n\\n        if ($search !== null && $search !== \'\') {\\n            $query->where(function ($q) use ($search) {\\n                $q->where(\'name\', \'like\', \'%\' . $search . \'%\')\\n                    ->orWhere(\'email\', \'like\', \'%\' . $search . \'%\');\\n            });\\n        }\\n\\n        return $query->paginate(10);\\n    }\\n\\n    public function vehicles(?string $search = null): \\\\Illuminate\\\\Pagination\\\\LengthAwarePaginator\\n    {\\n        $query = Vehicle::query()\\n            ->with([\\n                \'user:id,name\',\\n                \'tagPurchases\' => static function ($query) {\\n                    $query->orderByDesc(\'id\');\\n                },\\n            ])\\n            ->orderByDesc(\'created_at\');\\n\\n        if ($search !== null && $search !== \'\') {\\n            $query->where(function ($q) use ($search) {\\n                $q->where(\'name\', \'like\', \'%\' . $search . \'%\')\\n                    ->orWhereHas(\'user\', function ($q) use ($search) {\\n                        $q->where(\'name\', \'like\', \'%\' . $search . \'%\');\\n                    })\\n                    ->orWhere(\'plate\', \'like\', \'%\' . $search . \'%\')\\n                    ->orWhere(\'register_state\', \'like\', \'%\' . $search . \'%\')\\n                    ->orWhere(\'register_city\', \'like\', \'%\' . $search . \'%\');\\n            });\\n        }\\n\\n        return $query->paginate(10);\\n    }\\n\\n    public function tags(?string $search = null): \\\\Illuminate\\\\Pagination\\\\LengthAwarePaginator\\n    {\\n        $query = Tag::query()\\n            ->orderByDesc(\'created_at\');\\n\\n        if ($search !== null && $search !== \'\') {\\n            $query->where(function ($q) use ($search) {\\n                $q->where(\'name\', \'like\', \'%\' . $search . \'%\')\\n                    ->orWhere(\'slug\', \'like\', \'%\' . $search . \'%\')\\n                    ->orWhere(\'description\', \'like\', \'%\' . $search . \'%\')\\n                    ->orWhere(\'color_name\', \'like\', \'%\' . $search . \'%\');\\n            });\\n        }\\n\\n        return $query->paginate(10);\\n    }\\n\\n    public function discountCoupons(?string $search = null): \\\\Illuminate\\\\Pagination\\\\LengthAwarePaginator\\n    {\\n        $query = DiscountCoupon::query()\\n            ->withCount([\'tagPurchases as used_qty\'])\\n            ->orderByDesc(\'created_at\');\\n\\n        if ($search !== null && $search !== \'\') {\\n            $query->where(function ($q) use ($search) {\\n                $q->where(\'code\', \'like\', \'%\' . $search . \'%\')\\n                    ->orWhere(\'type\', \'like\', \'%\' . $search . \'%\')\\n                    ->orWhere(\'value\', \'like\', \'%\' . $search . \'%\')\\n                    ->orWhere(\'qty\', \'like\', \'%\' . $search . \'%\');\\n            });\\n        }\\n\\n        return $query->paginate(10);\\n    }\\n\\n    public function orders(?string $search = null): \\\\Illuminate\\\\Pagination\\\\LengthAwarePaginator\\n    {\\n        $query = TagPurchase::query()\\n            ->with([\\n                \'shipment\',\\n                \'tag:id,name,slug\',\\n                \'user:id,name\',\\n                \'vehicle:id,name,plate,color,year\',\\n            ])\\n            ->orderByDesc(\'created_at\');\\n\\n        if ($search !== null && $search !== \'\') {\\n            $query->where(function ($q) use ($search) {\\n                $q->where(\'mp_payment_id\', \'like\', \'%\' . $search . \'%\')\\n                    ->orWhere(\'id\', \'like\', \'%\' . $search . \'%\')\\n                    ->orWhereHas(\'user\', function ($userQuery) use ($search) {\\n                        $userQuery->where(\'name\', \'like\', \'%\' . $search . \'%\');\\n                    })\\n                    ->orWhereHas(\'vehicle\', function ($vehicleQuery) use ($search) {\\n                        $vehicleQuery\\n                            ->where(\'name\', \'like\', \'%\' . $search . \'%\')\\n                            ->orWhere(\'plate\', \'like\', \'%\' . $search . \'%\');\\n                    });\\n            });\\n        }\\n\\n        return $query->paginate(10);\\n    }\\n\\n    public function findTag(int $id): Tag\\n    {\\n        return Tag::query()->findOrFail($id);\\n    }\\n\\n    public function findDiscountCoupon(int $id): DiscountCoupon\\n    {\\n        return DiscountCoupon::query()\\n            ->withCount([\'tagPurchases as used_qty\'])\\n            ->findOrFail($id);\\n    }\\n\\n    public function createTag(array $data): Tag\\n    {\\n        return Tag::query()->create([\\n            \'name\' => $data[\'name\'],\\n            \'slug\' => $data[\'slug\'],\\n            \'description\' => $data[\'description\'] ?? null,\\n            \'color_name\' => $data[\'color_name\'],\\n            \'price\' => $data[\'price\'],\\n        ]);\\n    }\\n\\n    public function createDiscountCoupon(array $data): DiscountCoupon\\n    {\\n        return DiscountCoupon::query()->create([\\n            \'code\' => $data[\'code\'],\\n            \'type\' => $data[\'type\'],\\n            \'value\' => $data[\'value\'],\\n            \'qty\' => $data[\'qty\'] ?? null,\\n            \'expiration_date\' => $data[\'expiration_date\'] ?? null,\\n        ]);\\n    }\\n\\n    public function updateTag(int $id, array $data): Tag\\n    {\\n        $tag = Tag::query()->findOrFail($id);\\n\\n        $fields = [];\\n\\n        if (array_key_exists(\'name\', $data)) {\\n            $fields[\'name\'] = $data[\'name\'];\\n            $fields[\'slug\'] = $data[\'slug\'];\\n        }\\n\\n        foreach ([\'description\', \'color_name\', \'price\'] as $key) {\\n            if (array_key_exists($key, $data)) {\\n                $fields[$key] = $data[$key];\\n            }\\n        }\\n\\n        if ($fields !== []) {\\n            $tag->update($fields);\\n        }\\n\\n        return $tag->fresh();\\n    }\\n\\n    public function updateDiscountCoupon(int $id, array $data): DiscountCoupon\\n    {\\n        $coupon = DiscountCoupon::query()->findOrFail($id);\\n\\n        $fields = [];\\n\\n        foreach ([\'code\', \'type\', \'value\', \'qty\', \'expiration_date\'] as $key) {\\n            if (array_key_exists($key, $data)) {\\n                $fields[$key] = $data[$key];\\n            }\\n        }\\n\\n        if ($fields !== []) {\\n            $coupon->update($fields);\\n        }\\n\\n        return $coupon->fresh();\\n    }\\n\\n    public function deleteTag(int $id): void\\n    {\\n        $tag = Tag::query()->findOrFail($id);\\n\\n        $tag->delete();\\n    }\\n\\n    public function deleteDiscountCoupon(int $id): void\\n    {\\n        $coupon = DiscountCoupon::query()->findOrFail($id);\\n\\n        $coupon->delete();\\n    }\\n\\n    public function deleteVehicle(int $id): void\\n    {\\n        $vehicle = Vehicle::query()->findOrFail($id);\\n\\n        $vehicle->delete();\\n    }\\n\\n    public function updateOrderShipmentStatus(int $orderId, array $data): Shipment\\n    {\\n        $shipment = Shipment::query()\\n            ->where(\'tag_purchase_id\', $orderId)\\n            ->firstOrFail();\\n\\n        $status = (int) $data[\'status\'];\\n\\n        if (mb_strtolower((string) $shipment->carrier) === \'retirada\' && !in_array($status, PickupShipmentStatusEnum::values(), true)) {\\n            throw ValidationException::withMessages([\\n                \'status\' => [\'Para retirada, use apenas os status 0 (aguardando), 1 (disponivel para retirada) ou 4 (retirado).\'],\\n            ]);\\n        }\\n\\n        $payload = [\\n            \'status\' => $status,\\n            \'delivered_at\' => $status === 4 ? now() : null,\\n        ];\\n\\n        if (array_key_exists(\'tracking_code\', $data)) {\\n            $payload[\'tracking_code\'] = $data[\'tracking_code\'];\\n        }\\n\\n        $shipment->update($payload);\\n\\n        SendShipmentStatusUpdatedMailJob::dispatch((int) $shipment->id);\\n\\n        return $shipment->fresh();\\n    }\\n\\n    public function updateOrderStatus(int $orderId, int $status): TagPurchase\\n    {\\n        $order = TagPurchase::query()->findOrFail($orderId);\\n\\n        $order->update([\\n            \'status\' => $status,\\n            \'mp_payment_status\' => $this->resolveMpPaymentStatus($status),\\n        ]);\\n\\n        return $order->fresh();\\n    }\\n\\n    private function resolveMpPaymentStatus(int $status): string\\n    {\\n        return match ($status) {\\n            1 => \'approved\',\\n            2 => \'cancelled\',\\n            3 => \'rejected\',\\n            default => \'pending\',\\n        };\\n    }\\n\\n    public function dashboard(string $dateFrom, string $dateTo): array\\n    {\\n        $from = Carbon::parse($dateFrom)->startOfDay();\\n        $to   = Carbon::parse($dateTo)->endOfDay();\\n\\n        $totalUsers = User::query()\\n            ->where(\'type\', UserTypeEnum::Client->value)\\n            ->whereBetween(\'created_at\', [$from, $to])\\n            ->count();\\n\\n        $totalVehicles = Vehicle::query()\\n            ->whereBetween(\'created_at\', [$from, $to])\\n            ->count();\\n\\n        $totalOrders = TagPurchase::query()\\n            ->whereBetween(\'created_at\', [$from, $to])\\n            ->distinct(\'mp_payment_id\')\\n            ->count(\'mp_payment_id\');\\n\\n        $totalRevenue = TagPurchase::query()\\n            ->where(\'mp_payment_status\', \'approved\')\\n            ->whereBetween(\'created_at\', [$from, $to])\\n            ->sum(\'price_total\');\\n\\n        $latestUsers = User::query()\\n            ->where(\'type\', UserTypeEnum::Client->value)\\n            ->whereBetween(\'created_at\', [$from, $to])\\n            ->orderByDesc(\'created_at\')\\n            ->limit(10)\\n            ->get([\'id\', \'name\', \'email\', \'phone\', \'type\', \'created_at\']);\\n\\n        $latestOrderIds = TagPurchase::query()\\n            ->selectRaw(\'MAX(id) as id\')\\n            ->whereBetween(\'created_at\', [$from, $to])\\n            ->groupBy(\'mp_payment_id\')\\n            ->orderByRaw(\'MAX(created_at) DESC\')\\n            ->limit(4)\\n            ->pluck(\'id\');\\n\\n        $latestOrders = TagPurchase::query()\\n            ->with([\'vehicle:id,plate,name,color,year\', \'tag:id,name,slug\', \'shipment:id,tag_purchase_id,status\'])\\n            ->whereIn(\'id\', $latestOrderIds)\\n            ->orderByDesc(\'created_at\')\\n            ->get([\\n                \'id\',\\n                \'user_id\',\\n                \'vehicle_id\',\\n                \'tag_id\',\\n                \'mp_payment_id\',\\n                \'mp_payment_status\',\\n                \'payment_method\',\\n                \'qty\',\\n                \'price\',\\n                \'price_total\',\\n                \'shipping_price\',\\n                \'delivery\',\\n                \'pickup_point\',\\n                \'coupon_info\',\\n                \'mp_payment_status_detail\',\\n                \'status\',\\n                \'created_at\',\\n            ]);\\n\\n        return [\\n            \'totals\' => [\\n                \'users\'    => $totalUsers,\\n                \'vehicles\' => $totalVehicles,\\n                \'orders\'   => $totalOrders,\\n                \'revenue\'  => round((float) $totalRevenue, 2),\\n            ],\\n            \'latest_users\'  => $latestUsers,\\n            \'latest_orders\' => $latestOrders,\\n        ];\\n    }\\n\\n    // \\u2500\\u2500 Repasse de PDV \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\n\\n    public function pdvCommissions(?string $dateFrom, ?string $dateTo, ?int $adminId, ?string $search, int $perPage = 200): \\\\Illuminate\\\\Pagination\\\\LengthAwarePaginator\\n    {\\n        $from = $dateFrom !== null ? Carbon::parse($dateFrom)->startOfDay() : null;\\n        $to   = $dateTo !== null ? Carbon::parse($dateTo)->endOfDay() : null;\\n\\n        // One row per point; users only determine the existing sales attribution.\\n        $query = Pdv::query()->orderBy(\'name\');\\n        if ($adminId !== null) {\\n            $query->whereHas(\'users\', fn ($q) => $q->whereKey($adminId)->where(\'type\', UserTypeEnum::Admin->value));\\n        }\\n        if ($search !== null && $search !== \'\') {\\n            $query->where(function ($q) use ($search) {\\n                $q->where(\'name\', \'like\', \'%\' . $search . \'%\')\\n                    ->orWhereHas(\'users\', fn ($u) => $u->where(\'type\', UserTypeEnum::Admin->value)\\n                        ->where(fn ($a) => $a->where(\'name\', \'like\', \'%\' . $search . \'%\')->orWhere(\'email\', \'like\', \'%\' . $search . \'%\')));\\n            });\\n        }\\n        $points = $query->paginate($perPage);\\n        $points->getCollection()->transform(function (Pdv $point) use ($from, $to) {\\n            $admins = $point->users()->where(\'type\', UserTypeEnum::Admin->value)->pluck(\'id\');\\n            $sales = TagPurchase::query()->where(\'mp_payment_status\', \'approved\')\\n                ->whereHas(\'user\', fn ($q) => $q->whereIn(\'user_id_admin_pdv\', $admins));\\n            if ($from !== null) $sales->where(\'created_at\', \'>=\', $from);\\n            if ($to !== null) $sales->where(\'created_at\', \'<=\', $to);\\n            $totalQty = (int) (clone $sales)->sum(\'qty\');\\n            $totalAmount = round((float) (clone $sales)->sum(\'price_total\'), 2);\\n            return [\\n                \'pdv_id\' => $point->id,\\n                \'pdv_name\' => $point->name,\\n                \'staff_count\' => $admins->count(),\\n                \'commission_type\' => $point->commission_percentage === null ? null : 2,\\n                \'commission_type_label\' => $point->commission_percentage === null ? null : \'Percentual do PDV\',\\n                \'commission_value\' => $point->commission_percentage,\\n                \'commission_percentage\' => $point->commission_percentage,\\n                \'total_sales_qty\' => $totalQty,\\n                \'total_sales_amount\' => $totalAmount,\\n                \'commission_amount\' => $point->commissionAmount($totalAmount),\\n            ];\\n        });\\n        return $points;\\n    }\\n\\n    // \\u2500\\u2500 CRUD de usu\\u00e1rios \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\n\\n    public function findUser(int $id): User\\n    {\\n        return User::query()->findOrFail($id);\\n    }\\n\\n    public function createUser(array $data, User $authenticatedUser): User\\n    {\\n        if ((int)($data[\'type\']??3)!==3) throw ValidationException::withMessages([\'type\'=>\'Cadastre o administrador diretamente em Pontos de Venda.\']);\\n        $user = User::query()->create([\\n            \'name\'              => $data[\'name\'],\\n            \'email\'             => $data[\'email\'],\\n            \'password\'          => Hash::make($data[\'password\']),\\n            \'cpf\'               => $data[\'cpf\'] ?? null,\\n            \'birth_date\'        => $data[\'birth_date\'] ?? null,\\n            \'phone\'             => $data[\'phone\'] ?? null,\\n            \'type\'              => UserTypeEnum::Client->value,\\n            \'pdv_id\'            => $data[\'pdv_id\'] ?? null,\\n            // \'user_id_admin_pdv\' => $data[\'user_id_admin_pdv\'] ?? null,\\n        ]);\\n\\n        CreateDefaultUserSettingsJob::dispatch($authenticatedUser->id);\\n\\n        return $user;\\n    }\\n\\n    public function updateUser(int $id, array $data): User\\n    {\\n        if (array_key_exists(\'type\',$data) && (int)$data[\'type\']!==3) throw ValidationException::withMessages([\'type\'=>\'Gerencie administradores em Pontos de Venda.\']);\\n        $user = User::query()->findOrFail($id);\\n\\n        $this->ensureClient($user);\\n\\n        $fields = array_filter([\\n            \'name\'              => $data[\'name\'] ?? null,\\n            \'email\'             => $data[\'email\'] ?? null,\\n            \'cpf\'               => $data[\'cpf\'] ?? null,\\n            \'birth_date\'        => $data[\'birth_date\'] ?? null,\\n            \'phone\'             => $data[\'phone\'] ?? null,\\n            \'type\'              => $data[\'type\'] ?? null,\\n        ], fn($v) => $v !== null);\\n\\n        // Nullable fields must be handled explicitly\\n        foreach ([\'pdv_id\', \'user_id_admin_pdv\'] as $key) {\\n            if (array_key_exists($key, $data)) {\\n                $fields[$key] = $data[$key];\\n            }\\n        }\\n\\n        if (!empty($data[\'password\'])) {\\n            $fields[\'password\'] = Hash::make($data[\'password\']);\\n        }\\n\\n        $user->update($fields);\\n\\n        return $user->fresh();\\n    }\\n\\n    public function deleteUser(int $id): void\\n    {\\n        $user = User::query()->findOrFail($id);\\n\\n        $this->ensureClient($user);\\n\\n        $user->delete();\\n    }\\n\\n    private function ensureClient(User $user): void\\n    {\\n        if ($user->type !== UserTypeEnum::Client->value) {\\n            throw new AuthorizationException(\'Gerencie administradores em Pontos de Venda. A conta Super Admin \\u00e9 preservada.\');\\n        }\\n    }\\n\\n    // \\u2500\\u2500 CRUD de FAQs \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\n\\n    public function faqs(?string $search = null): \\\\Illuminate\\\\Pagination\\\\LengthAwarePaginator\\n    {\\n        $query = Faq::query()->orderByRaw(\'`order` IS NULL ASC, `order` ASC\')->orderBy(\'id\');\\n\\n        if ($search !== null && $search !== \'\') {\\n            $query->where(function ($q) use ($search) {\\n                $q->where(\'question\', \'like\', \'%\' . $search . \'%\')\\n                    ->orWhere(\'answer\', \'like\', \'%\' . $search . \'%\');\\n            });\\n        }\\n\\n        return $query->paginate(10);\\n    }\\n\\n    public function findFaq(int $id): Faq\\n    {\\n        return Faq::query()->findOrFail($id);\\n    }\\n\\n    public function createFaq(array $data): Faq\\n    {\\n        return Faq::query()->create([\\n            \'question\' => $data[\'question\'],\\n            \'answer\'   => $data[\'answer\'],\\n            \'active\'   => $data[\'active\'] ?? true,\\n            \'order\'    => $data[\'order\'] ?? null,\\n        ]);\\n    }\\n\\n    public function updateFaq(int $id, array $data): Faq\\n    {\\n        $faq = Faq::query()->findOrFail($id);\\n\\n        $fields = [];\\n\\n        foreach ([\'question\', \'answer\', \'active\', \'order\'] as $key) {\\n            if (array_key_exists($key, $data)) {\\n                $fields[$key] = $data[$key];\\n            }\\n        }\\n\\n        if ($fields !== []) {\\n            $faq->update($fields);\\n        }\\n\\n        return $faq->fresh();\\n    }\\n\\n    public function deleteFaq(int $id): void\\n    {\\n        $faq = Faq::query()->findOrFail($id);\\n\\n        $faq->delete();\\n    }\\n\\n    public function reorderFaq(int $id, int $newOrder): Faq\\n    {\\n        $faq      = Faq::query()->findOrFail($id);\\n        $oldOrder = $faq->order; // mant\\u00e9m null se n\\u00e3o tiver ordem definida\\n\\n        if ($oldOrder !== null && (int) $oldOrder === $newOrder) {\\n            return $faq;\\n        }\\n\\n        if ($oldOrder === null) {\\n            // Item sem ordem definida: abre espa\\u00e7o na posi\\u00e7\\u00e3o destino\\n            Faq::query()\\n                ->where(\'id\', \'!=\', $id)\\n                ->where(\'order\', \'>=\', $newOrder)\\n                ->increment(\'order\');\\n        } elseif ($newOrder > (int) $oldOrder) {\\n            // Movendo para baixo: registros entre (old+1) e new sobem uma posi\\u00e7\\u00e3o\\n            Faq::query()\\n                ->where(\'id\', \'!=\', $id)\\n                ->whereBetween(\'order\', [(int) $oldOrder + 1, $newOrder])\\n                ->decrement(\'order\');\\n        } else {\\n            // Movendo para cima: registros entre new e (old-1) descem uma posi\\u00e7\\u00e3o\\n            Faq::query()\\n                ->where(\'id\', \'!=\', $id)\\n                ->whereBetween(\'order\', [$newOrder, (int) $oldOrder - 1])\\n                ->increment(\'order\');\\n        }\\n\\n        $faq->update([\'order\' => $newOrder]);\\n\\n        return $faq->fresh();\\n    }\\n}\\n", "test-dashboard-order.php": "<?php\\n$root=$argv[1];$stage=$argv[2];require $root.\'/vendor/autoload.php\';require $stage.\'/app/Services/AdminService.php\';$app=require $root.\'/bootstrap/app.php\';$app->make(Illuminate\\\\Contracts\\\\Console\\\\Kernel::class)->bootstrap();\\nuse Illuminate\\\\Support\\\\Facades\\\\{DB,Schema,Mail,Queue,Http};use Illuminate\\\\Database\\\\Schema\\\\Blueprint;use App\\\\Models\\\\{User,Vehicle,Tag,TagPurchase,Shipment};use App\\\\Services\\\\AdminService;\\nconfig([\'database.default\'=>\'summary_memory\',\'database.connections.summary_memory\'=>[\'driver\'=>\'sqlite\',\'database\'=>\':memory:\',\'prefix\'=>\'\',\'foreign_key_constraints\'=>true],\'cache.default\'=>\'array\']);DB::setDefaultConnection(\'summary_memory\');if(DB::connection()->getDatabaseName()!==\':memory:\')throw new RuntimeException(\'Memory guard failed\');Mail::fake();Queue::fake();Http::preventStrayRequests();\\nSchema::create(\'users\',function(Blueprint $t){$t->id();$t->string(\'name\');$t->string(\'email\');$t->string(\'phone\')->nullable();$t->integer(\'type\');$t->softDeletes();$t->timestamps();});\\nSchema::create(\'vehicles\',function(Blueprint $t){$t->id();$t->integer(\'user_id\');foreach([\'name\',\'plate\',\'color\',\'year\'] as $c)$t->string($c)->nullable();$t->timestamps();});\\nSchema::create(\'tags\',function(Blueprint $t){$t->id();$t->string(\'name\');$t->string(\'slug\');$t->softDeletes();$t->timestamps();});\\nSchema::create(\'tags_purchases\',function(Blueprint $t){$t->id();foreach([\'user_id\',\'vehicle_id\',\'tag_id\',\'qty\'] as $c)$t->integer($c)->nullable();foreach([\'mp_payment_id\',\'mp_payment_status\',\'mp_payment_status_detail\',\'payment_method\'] as $c)$t->string($c)->nullable();foreach([\'price\',\'price_total\',\'shipping_price\'] as $c)$t->decimal($c,8,2)->default(0);foreach([\'delivery\',\'pickup_point\',\'coupon_info\'] as $c)$t->json($c)->nullable();$t->integer(\'status\')->default(1);$t->softDeletes();$t->timestamps();});\\nSchema::create(\'shipments\',function(Blueprint $t){$t->id();$t->integer(\'tag_purchase_id\');$t->integer(\'status\')->default(0);$t->string(\'carrier\')->nullable();$t->softDeletes();$t->timestamps();});\\n$n=0;$ok=function($c,$m)use(&$n){if(!$c)throw new RuntimeException($m);$n++;};$client=User::create([\'name\'=>\'QA\',\'email\'=>\'qa@example.test\',\'type\'=>3]);$v=Vehicle::create([\'user_id\'=>$client->id,\'plate\'=>\'ABC1D23\']);$tag=Tag::create([\'name\'=>\'Etiqueta Verde\',\'slug\'=>\'verde\']);\\n$base=[\'user_id\'=>$client->id,\'vehicle_id\'=>$v->id,\'tag_id\'=>$tag->id,\'qty\'=>1,\'price\'=>29.90,\'price_total\'=>0,\'shipping_price\'=>0,\'status\'=>1,\'payment_method\'=>\'free\',\'mp_payment_id\'=>\'FREE_QA\',\'mp_payment_status\'=>\'approved\',\'mp_payment_status_detail\'=>\'coupon_full_discount\',\'pickup_point\'=>[\'id\'=>10,\'label\'=>\'PDV QA\'],\'coupon_info\'=>[\'type\'=>1,\'value\'=>100]];\\n$order=TagPurchase::create($base);$ship=Shipment::create([\'tag_purchase_id\'=>$order->id,\'status\'=>0,\'carrier\'=>\'retirada\']);$svc=new AdminService;$from=now()->startOfYear()->format(\'Y-m-d\');$to=now()->format(\'Y-m-d\');$result=$svc->dashboard($from,$to);$recent=$result[\'latest_orders\']->first();\\n$ok($recent->pickup_point[\'id\']===10,\'point id included\');$ok($recent->pickup_point[\'label\']===\'PDV QA\',\'point name included\');$ok($recent->relationLoaded(\'shipment\')&&$recent->shipment->status==0,\'waiting pickup state included\');$ok($recent->tag->name===\'Etiqueta Verde\',\'tag name included\');$ok($recent->delivery===null,\'pickup remains distinct from delivery\');$ok($recent->mp_payment_status===\'approved\',\'coupon approval preserved\');$ok($recent->mp_payment_status_detail===\'coupon_full_discount\',\'free approval cause included\');$ok((float)$recent->price_total===0.0,\'zero charge preserved\');$ok($result[\'totals\'][\'orders\']===1,\'free order counted\');$ok((float)$result[\'totals\'][\'revenue\']===0.0,\'coupon is not revenue\');\\n$ship->update([\'status\'=>4]);$updated=$svc->dashboard($from,$to)[\'latest_orders\']->first();$ok($updated->shipment->status==4,\'confirmed withdrawal state current\');$ok($updated->pickup_point[\'id\']===10,\'pickup preference retained after delivery\');\\n$paid=TagPurchase::create([...$base,\'mp_payment_id\'=>\'PAID_QA\',\'payment_method\'=>\'pix\',\'price_total\'=>29.90,\'pickup_point\'=>null,\'delivery\'=>[\'city\'=>\'QA\']]);$totals=$svc->dashboard($from,$to)[\'totals\'];$ok((float)$totals[\'revenue\']===29.90,\'paid revenue unaffected\');$ok($totals[\'orders\']===2,\'order count unchanged\');$ok(TagPurchase::find($order->id)->mp_payment_status===\'approved\',\'summary does not change payment\');Mail::assertNothingSent();$ok(true,\'no mail sent\');echo \'PASS \'.$n.\' isolated dashboard order checks; memory only, fake mail/queue, no payment calls.\'.PHP_EOL;\\n"}')
